class ProviderApiError(RuntimeError):
    """Typed failure with no credential, phone number, or raw response leakage."""

    def __init__(self, provider: str, endpoint: str, state: ProviderHealth | OperationState) -> None:
        self.provider = provider
        self.endpoint = endpoint
        self.state = state
        super().__init__(f"{provider}:{endpoint}:{state.value}")


def redact_secret(value: str | None) -> str:
    """Return a stable non-secret status, never a key fragment or fingerprint."""
    return "NOT_CONFIGURED" if not value else "CONFIGURED"


def resolve_google_service(services: tuple[Service, ...]) -> Service | None:
    """Return one unambiguous Google/Gmail service, avoiding unrelated matches."""
    matches = [
        service
        for service in services
        if re.search(r"(^|[^a-z0-9])(google|gmail)([^a-z0-9]|$)", service.name.casefold())
    ]
    return matches[0] if len(matches) == 1 else None


def map_endpoint_code(
    endpoint: str,
    code: str | int | None,
    mappings: Mapping[tuple[str, str], OperationState],
) -> OperationState:
    """Map an error only using its documented endpoint/action and code."""
    if code is None:
        return OperationState.PROVIDER_ERROR
    return mappings.get((endpoint, str(code)), OperationState.PROVIDER_ERROR)


def normalize_phone_number(
    raw_number: str,
    calling_code: str,
    *,
    representation: str,
) -> str | None:
    """Normalize only from explicit provider country semantics; never guess."""
    digits = re.sub(r"\D", "", raw_number)
    country_digits = re.sub(r"\D", "", calling_code)
    if not digits or not country_digits:
        return None
    if representation == "E164":
        if raw_number.strip().startswith("+"):
            return f"+{digits}"
        if digits.startswith(country_digits):
            return f"+{digits}"
        return f"+{country_digits}{digits.lstrip('0')}"
    if representation == "NATIONAL" and digits.startswith(country_digits):
        return digits[len(country_digits):]
    if representation == "NATIONAL":
        return digits
    return None


def failover_state(current: OperationState, replacement_attempts: int, maximum_replacements: int = 1) -> OperationState:
    """Permit bounded delivery recovery but never rotate after Google rejection."""
    if current in {OperationState.NUMBER_REJECTED, OperationState.NEEDS_OPERATOR}:
        return current
    if current in {OperationState.OTP_TIMEOUT, OperationState.PROVIDER_ERROR} and replacement_attempts < maximum_replacements:
        return OperationState.NUMBER_ACQUIRING
    return OperationState.RECONCILE_REQUIRED


def otp_submission_state(submit_count: int, observed_result: bool) -> OperationState:
    """One OTP submission only; ambiguity requires remote reconciliation."""
    if submit_count > 1:
        return OperationState.RECONCILE_REQUIRED
    if submit_count == 1 and not observed_result:
        return OperationState.RECONCILE_REQUIRED
    return OperationState.OTP_RECEIVED


def thumbnail_upload_state(dispatch_count: int, persisted: bool) -> str:
    """A thumbnail is verified only after one dispatch and remote persistence."""
    if dispatch_count != 1:
        return "RECONCILE_REQUIRED"
    return "VERIFIED" if persisted else "RECONCILE_REQUIRED"
"""Secret-safe, contract-unverified ViOTP adapter configuration.

The live ViOTP API contract must be read from the authenticated provider
dashboard before any HTTP operation is implemented.  This module therefore
does not guess paths, methods, authentication headers, or response shapes.
"""
from __future__ import annotations

from dataclasses import dataclass, field
import os
from pathlib import Path
import json
from typing import Any, Callable, Mapping
from urllib.parse import urlencode
from urllib.request import Request, urlopen

try:
    from phone_verification_provider import NumberLease, OperationState, OtpResult, ProviderApiError, ProviderHealth, Service
except ImportError:  # pragma: no cover - package-style invocation
    from probes.phone_verification_provider import NumberLease, OperationState, OtpResult, ProviderApiError, ProviderHealth, Service


API_KEY_ENV = "VIOTP_API_KEY"
DEFAULT_KEY_FILE = Path(__file__).resolve().parent.parent / "secrets" / "viotp_api.txt"
API_BASE_URL = "https://api.viotp.com"
JsonTransport = Callable[[str], object]


@dataclass(frozen=True)
class ViOtpApi:
    """Local-only key holder that never serializes the full credential."""

    api_key: str | None = field(repr=False)

    @classmethod
    def from_environment(
        cls,
        environ: dict[str, str] | None = None,
        key_file: Path | None = None,
    ) -> "ViOtpApi":
        values = os.environ if environ is None else environ
        value = values.get(API_KEY_ENV, "").strip()
        if not value:
            secret_path = DEFAULT_KEY_FILE if key_file is None else key_file
            if secret_path.is_file():
                value = next(
                    (
                        line.strip()
                        for line in secret_path.read_text(encoding="utf-8").splitlines()
                        if line.strip() and not line.lstrip().startswith("#") and not line.strip().startswith("PASTE_")
                    ),
                    "",
                )
        return cls(api_key=value or None)

    @property
    def configured(self) -> bool:
        return self.api_key is not None

    @property
    def health_state(self) -> str:
        """Return only a truthful local configuration state; no network call occurs."""
        return "CONTRACT_UNVERIFIED" if self.configured else "NOT_CONFIGURED"

    @property
    def redacted_key(self) -> str:
        if self.api_key is None:
            return "NOT_CONFIGURED"
        return "CONFIGURED"

    def require_documented_contract(self) -> None:
        """Fail closed until the authenticated dashboard supplies an API contract."""
        if not self.configured:
            raise RuntimeError(f"{API_KEY_ENV} is not configured")
        raise RuntimeError("ViOTP API contract has not been verified from the authenticated dashboard")

    def get_balance(self, transport: JsonTransport | None = None) -> int:
        payload = self._fetch("/users/balance", {}, transport)
        data = self._require_success("users.balance", payload)
        try:
            return int(data["balance"])
        except (KeyError, TypeError, ValueError) as exc:
            raise ProviderApiError("VIOTP", "users.balance", OperationState.PROVIDER_ERROR) from exc

    def list_networks(self, transport: JsonTransport | None = None) -> tuple[Service, ...]:
        payload = self._fetch("/networks/get", {}, transport)
        data = self._require_success("networks.get", payload)
        if not isinstance(data, list):
            raise ProviderApiError("VIOTP", "networks.get", OperationState.PROVIDER_ERROR)
        return tuple(Service(provider_service_id=str(item["id"]), name=str(item["name"])) for item in data)

    def list_services(self, country: str = "vn", transport: JsonTransport | None = None) -> tuple[Service, ...]:
        payload = self._fetch("/service/getv2", {"country": country}, transport)
        data = self._require_success("service.getv2", payload)
        if not isinstance(data, list):
            raise ProviderApiError("VIOTP", "service.getv2", OperationState.PROVIDER_ERROR)
        return tuple(
            Service(
                provider_service_id=str(item["id"]),
                name=str(item["name"]),
                country_code=country.upper(),
                price=str(item["price"]) if item.get("price") is not None else None,
            )
            for item in data
        )

    def resolve_service(self, name: str, country: str = "vn", transport: JsonTransport | None = None) -> Service | None:
        """Resolve only one exact documented provider label; never fuzzy-pick."""
        wanted = name.casefold().strip()
        matches = [item for item in self.list_services(country, transport) if item.name.casefold().strip() == wanted]
        return matches[0] if len(matches) == 1 else None

    def resolve_google_service(self, country: str = "vn", transport: JsonTransport | None = None) -> Service | None:
        """Resolve the one exact Gmail/Google label exposed by the live API."""
        return self.resolve_service("Gmail/Google", country, transport)

    def resolve_youtube_service(self, country: str = "vn", transport: JsonTransport | None = None) -> Service | None:
        """Resolve only ViOTP's current, distinct YouTube service label.

        A Google/Gmail item is deliberately not an alias here.  The caller can
        only acquire when the current provider catalog contains one exact
        YouTube item, which makes a catalog rename or duplicate fail closed.
        """
        return self.resolve_service("Youtube", country, transport)

    def resolve_network(self, name: str, transport: JsonTransport | None = None) -> Service | None:
        """Resolve one exact current provider network label; never hard-code IDs."""
        wanted = name.casefold().strip()
        matches = [item for item in self.list_networks(transport) if item.name.casefold().strip() == wanted]
        return matches[0] if len(matches) == 1 else None

    def acquire_number(
        self,
        service: Service,
        *,
        country: str = "vn",
        network: str | None = None,
        transport: JsonTransport | None = None,
    ) -> NumberLease:
        """Acquire one documented lease; caller owns all retry/failover policy.

        ViOTP documents the Vietnamese ``network`` parameter as its symbolic
        name (for example ``VINAPHONE``), not the numeric ID returned by the
        network catalog.  The IDs remain useful for identification only.
        """
        parameters = {"serviceId": service.provider_service_id, "country": country}
        if network:
            parameters["network"] = network
        data = self._require_success("request.getv2", self._fetch("/request/getv2", parameters, transport))
        if not isinstance(data, Mapping):
            raise ProviderApiError("VIOTP", "request.getv2", OperationState.PROVIDER_ERROR)
        try:
            request_id = str(data["request_id"])
            phone_number = str(data["phone_number"])
        except (KeyError, TypeError, ValueError) as exc:
            raise ProviderApiError("VIOTP", "request.getv2", OperationState.PROVIDER_ERROR) from exc
        if not request_id or not phone_number:
            raise ProviderApiError("VIOTP", "request.getv2", OperationState.PROVIDER_ERROR)
        return NumberLease(
            provider="VIOTP",
            service=service,
            request_id=request_id,
            phone_number=phone_number,
            country_code=str(data["countryCode"]) if data.get("countryCode") is not None else None,
            country_iso=str(data["countryISO"]) if data.get("countryISO") is not None else None,
        )

    def get_order(self, order_id: str, transport: JsonTransport | None = None) -> OtpResult:
        data = self._require_success("session.getv2", self._fetch("/session/getv2", {"requestId": order_id}, transport))
        if not isinstance(data, Mapping):
            raise ProviderApiError("VIOTP", "session.getv2", OperationState.PROVIDER_ERROR)
        status = str(data.get("Status", ""))
        state = {"0": OperationState.WAITING_FOR_OTP, "1": OperationState.OTP_RECEIVED, "2": OperationState.EXPIRED}.get(status)
        if state is None:
            raise ProviderApiError("VIOTP", "session.getv2", OperationState.PROVIDER_ERROR)
        code = str(data["Code"]) if data.get("Code") is not None else None
        if state is OperationState.OTP_RECEIVED and not code:
            raise ProviderApiError("VIOTP", "session.getv2", OperationState.PROVIDER_ERROR)
        return OtpResult(provider="VIOTP", request_id=order_id, state=state, code=code)

    def wait_for_otp(self, order_id: str, transport: JsonTransport | None = None) -> OtpResult:
        """One read only.  Timed polling is an explicit orchestration decision."""
        return self.get_order(order_id, transport)

    def _fetch(self, path: str, parameters: Mapping[str, str], transport: JsonTransport | None) -> Mapping[str, Any]:
        if not self.api_key:
            raise ProviderApiError("VIOTP", path, ProviderHealth.NOT_CONFIGURED)
        query = urlencode({"token": self.api_key, **parameters})
        url = f"{API_BASE_URL}{path}?{query}"
        try:
            payload = (transport or _read_json)(url)
        except Exception as exc:  # the URL must never be included in the exception
            raise ProviderApiError("VIOTP", path, ProviderHealth.UNAVAILABLE) from exc
        if not isinstance(payload, Mapping):
            raise ProviderApiError("VIOTP", path, OperationState.PROVIDER_ERROR)
        return payload

    def _require_success(self, endpoint: str, payload: Mapping[str, Any]) -> Any:
        code = str(payload.get("status_code", ""))
        if payload.get("success") is True and code == "200":
            return payload.get("data")
        state = {
            "401": ProviderHealth.AUTH_FAILED,
            "429": OperationState.TOO_MANY_PENDING,
            "-2": OperationState.INSUFFICIENT_BALANCE,
            "-3": OperationState.NO_STOCK,
            "-4": OperationState.SERVICE_UNAVAILABLE,
        }.get(code, OperationState.PROVIDER_ERROR)
        raise ProviderApiError("VIOTP", endpoint, state)


def _read_json(url: str) -> object:
    request = Request(url, headers={"User-Agent": "Multiple-Automation-Capability-Validation/1.0", "Accept": "application/json"})
    with urlopen(request, timeout=30) as response:  # nosec B310 - exact authenticated official API base
        return json.loads(response.read().decode("utf-8"))


